const p = msg.payload;

const NOMS = {
    hr: "fréquence cardiaque", o2sat: "saturation en oxygène", temp: "température",
    sbp: "pression systolique", map: "pression moyenne", dbp: "pression diastolique",
    resp: "fréquence respiratoire", indice_choc: "indice de choc",
    pression_pulsee: "pression pulsée"
};
const raisons = [...new Set((p.risque_explication || [])
    .filter(v => !v.endsWith("_age") && v !== "heure_sejour")
    .map(v => NOMS[v] || NOMS[v.split("_")[0]] || v))];

const risque = p.risque_edge !== undefined ? Math.round(p.risque_edge * 1000) / 10 : null;
const lieu = "Service " + p.service + ", lit " + p.lit;
let texte;

if (p.alerte === "fin") {
    texte = "FIN D'ALERTE - " + lieu + " : situation revenue au calme";
} else {
    if (p.priorite === "critique") {
        texte = "CRITIQUE - " + lieu + " : NEWS2 à " + p.news2 + " et risque de sepsis " + risque + " %";
    } else if (p.priorite === "urgente") {
        texte = "URGENT - " + lieu + " : NEWS2 à " + p.news2;
    } else {
        texte = "VIGILANCE - " + lieu + " : risque de sepsis " + risque + " %";
    }
    if (raisons.length > 0 && p.priorite !== "urgente") {
        texte += " (" + raisons.join(", ") + ")";
    }
    if (p.alerte === "rappel") {
        texte = "RAPPEL - " + texte;
    }
}

msg.topic = "hopital/alertes/service-" + p.service;
msg.payload = {
    alerte: p.alerte,
    type: p.priorite,
    patient_id: p.patient_id,
    service: p.service,
    lit: p.lit,
    news2: p.news2,
    risque_edge: p.risque_edge,
    raisons: raisons,
    timestamp: p.timestamp,
    message: texte
};
return msg;

// Nom et service de la passerelle, tirés du sujet : hopital/etat/passerelle-2
const nom = msg.topic.split("/").pop();
const service = Number(nom.split("-")[1]);

// Dernier état connu de chaque passerelle
const etats = flow.get("etats_passerelles") || {};
const avant = etats[nom];
etats[nom] = msg.payload;
flow.set("etats_passerelles", etats);

let alerte, texte;
if (msg.payload === "hors ligne") {
    alerte = "panne";
    texte = "PANNE - " + nom + " hors ligne : les 20 lits du service "
          + service + " ne sont plus surveillés";
} else if (msg.payload === "en ligne" && avant === "hors ligne") {
    alerte = "retour";
    texte = "RETOUR - " + nom + " de nouveau en ligne : surveillance du service "
          + service + " rétablie";
} else {
    return null;   // passerelle en ligne au démarrage : rien à signaler
}

msg.topic = "hopital/alertes/technique";
msg.payload = {
    alerte: alerte,
    type: "technique",
    service: service,
    passerelle: nom,
    timestamp: new Date().toISOString(),
    message: texte
};
return msg;
